terraform {
  required_providers {
    proxmox = {
      source  = "bpg/proxmox"
      version = "~> 0.69"
    }
    time = {
      source  = "hashicorp/time"
      version = "~> 0.12"
    }
    null = {
      source  = "hashicorp/null"
      version = "~> 3.2"
    }
  }
}

resource "proxmox_virtual_environment_container" "lxc" {
  node_name   = var.proxmox_node
  vm_id       = var.container_id
  description = var.description
  tags        = var.tags

  # Template
  operating_system {
    template_file_id = var.template
    type             = var.os_type
  }

  # Compute
  cpu {
    cores = var.cores
  }

  memory {
    dedicated = var.memory
    swap      = var.swap
  }

  # Root filesystem
  disk {
    datastore_id = var.rootfs_storage
    size         = var.rootfs_size
  }

  # Additional mount points
  dynamic "mount_point" {
    for_each = var.mount_points
    content {
      volume = mount_point.value.volume
      path   = mount_point.value.path
      backup = mount_point.value.backup
      quota  = mount_point.value.quota
    }
  }

  # Primary network - Container network (vmbr1, 10.100.x.x)
  network_interface {
    name   = "eth0"
    bridge = "vmbr1"
  }

  # Secondary network - LAN (vmbr0, 192.168.1.x) - only if lan_ip is set
  dynamic "network_interface" {
    for_each = var.lan_ip != "" ? [1] : []
    content {
      name   = "eth1"
      bridge = "vmbr0"
    }
  }

  initialization {
    hostname = var.name

    # eth0 - Container network (required)
    ip_config {
      ipv4 {
        address = var.container_ip
        gateway = var.container_gateway
      }
    }

    # eth1 - LAN network (optional)
    dynamic "ip_config" {
      for_each = var.lan_ip != "" ? [1] : []
      content {
        ipv4 {
          address = var.lan_ip
          gateway = null  # Don't set gateway on secondary interface
        }
      }
    }

    user_account {
      keys = [var.ssh_public_key]
    }
  }

  # GPU Device Passthrough and custom devices are configured via SSH
  # The API token doesn't have permission for device_passthrough (requires root@pam)
  # See null_resource.configure_gpu_passthrough below

  # Container features
  # Note: API tokens can only set features on unprivileged containers
  # For privileged containers, all features are configured via SSH in configure_container_features
  dynamic "features" {
    for_each = var.unprivileged ? [1] : []
    content {
      nesting = var.enable_nesting
    }
  }

  unprivileged = var.unprivileged

  # Lifecycle
  started       = var.start_on_create
  start_on_boot = var.start_on_boot

  # Lifecycle - ignore create-time-only attributes that would force replacement
  # These attributes cannot be changed on existing containers and must be ignored
  # for imported containers to work properly
  lifecycle {
    ignore_changes = [
      # These are create-time-only and would force replacement if changed
      operating_system,   # template_file_id
      initialization,     # user_account.keys, hostname
      unprivileged,       # cannot change privileged/unprivileged after creation
      disk,               # cannot change storage or reduce size after creation
      features,           # API token can't modify features on privileged containers (requires root@pam)
      tags,               # tags are additionally modified via cron jobs outside of Terraform
      device_passthrough, # GPU devices may be added manually via SSH (API token can't manage these)
      console,            # console settings may be modified outside of Terraform
      start_on_boot,      # may be set outside of Terraform
      mount_point,        # mount points configured outside Terraform (API token limitations)
      # Timeout values are not actual container properties, ignore them on imported resources
      timeout_clone,
      timeout_create,
      timeout_delete,
      timeout_start,
      timeout_update,
    ]
  }
}

# Configure container features via SSH to Proxmox host
# The API token cannot set keyctl or fuse - requires root@pam
# This configures:
#   - For privileged: lxc.apparmor.profile: unconfined (required for Docker)
#   - For all containers: features: nesting, keyctl, fuse (if enabled via variables)
resource "null_resource" "configure_container_features" {

# =============================================================================
# Traefik Route Module
# =============================================================================
# Generates and syncs Traefik dynamic configuration for an app.
# Each app can self-register its routes without modifying Traefik configs.
#
# Features:
# - Auto-generates YAML config from variables
# - Syncs to Traefik LXC via file-sync module
# - Supports internal (websecure) and public (web) routes
# - Health checks, middlewares, custom options
#
# Usage:
#   module "n8n_route" {
#     source = "../../modules/traefik-route"
#
#     app_name    = "n8n"
#     backend_url = "http://192.168.1.213:5678"
#
#     internal_domain = "n8n.homelab.rambtech.dev"
#     public_domain   = ""  # Optional
#
#     traefik_host         = "192.168.1.162"
#     ssh_private_key_path = var.ssh_private_key_path
#   }
# =============================================================================

terraform {
  required_providers {
    local = {
      source = "hashicorp/local"
    }
    filesync = {
      source = "darshan-rambhia/filesync"
    }
    null = {
      source = "hashicorp/null"
    }
  }
}

# -----------------------------------------------------------------------------
# Route Configuration Templates
# -----------------------------------------------------------------------------

locals {
  # Internal route (websecure with TLS)
  internal_route = var.internal_domain != "" ? {
    rule        = "Host(`${var.internal_domain}`)"
    entryPoints = var.internal_entrypoint
    service     = var.app_name
    tls = {
      certResolver = var.cert_resolver
    }
    middlewares = var.internal_middlewares
  } : null

  # Public route (web HTTP - Cloudflare Flexible SSL forwards HTTP to origin)
  public_route = var.public_domain != "" ? {
    rule        = "Host(`${var.public_domain}`)"
    entryPoints = var.public_entrypoint
    service     = var.app_name
    middlewares = var.public_middlewares
  } : null

  # Service configuration
  service_config = {
    loadBalancer = merge(
      {
        servers = [
          { url = var.backend_url }
        ]
      },
      var.health_check != null ? { healthCheck = var.health_check } : {}
    )
  }

  # Complete Traefik config
  traefik_config = {
    http = {
      routers = merge(
        local.internal_route != null ? { "${var.app_name}" = local.internal_route } : {},
        local.public_route != null ? { "${var.app_name}-public" = local.public_route } : {}
      )
      services = {
        "${var.app_name}" = local.service_config
      }
    }
  }

  # YAML output
  config_yaml = yamlencode(local.traefik_config)

  # Target path on Traefik LXC
  remote_config_path = "/config/dynamic/${var.app_name}.yml"
}

# -----------------------------------------------------------------------------
# Write Config to Temporary File
# -----------------------------------------------------------------------------

# =============================================================================
# Shared Configuration
# =============================================================================
# This file is symlinked into each app directory to provide common variables
# and provider configuration. Each app has its own state file.
#
# Secret Management:
# - State encryption passphrase: Must remain as TF_VAR (needed before providers init)
# - All other secrets: Fetched from 1Password via onepassword provider
# =============================================================================

# -----------------------------------------------------------------------------
# State Encryption (Required as TF_VAR - runs before providers)
# -----------------------------------------------------------------------------

variable "state_encryption_passphrase" {
  description = "Passphrase for encrypting state files (from 1Password: op://homelab/opentofu/password)"
  type        = string
  sensitive   = true
}

# -----------------------------------------------------------------------------
# Proxmox Configuration
# -----------------------------------------------------------------------------

variable "proxmox_endpoint" {
  description = "Proxmox API endpoint URL"
  type        = string
  default     = "https://192.168.1.215:8006"
}

variable "proxmox_node" {
  description = "Proxmox node name"
  type        = string
  default     = "pve"
}

variable "proxmox_ssh_host" {
  description = "Proxmox host SSH address (for configuring privileged containers)"
  type        = string
  default     = "192.168.1.215"
}

# -----------------------------------------------------------------------------
# SSH Configuration
# -----------------------------------------------------------------------------

variable "ssh_private_key_path" {
  description = "Path to SSH private key"
  type        = string
  default     = "~/.ssh/homelab_ed25519"
}

variable "ssh_public_key_path" {
  description = "Path to SSH public key"
  type        = string
  default     = "~/.ssh/homelab_ed25519.pub"
}

# -----------------------------------------------------------------------------
# Storage & Network Defaults
# -----------------------------------------------------------------------------

variable "default_storage" {
  description = "Default storage for LXC containers"
  type        = string
  default     = "tank"
}

variable "default_bridge" {
  description = "Default network bridge"
  type        = string
  default     = "vmbr0"
}

variable "lxc_template" {
  description = "Default LXC template (base Debian)"
  type        = string
  default     = "local:vztmpl/debian-13-standard_13.1-2_amd64.tar.zst"
}

variable "lxc_template_docker" {
  description = "LXC template with Docker pre-installed"
  type        = string
  default     = "local:vztmpl/debian-13-docker_1.0_amd64.tar.zst"
}

# -----------------------------------------------------------------------------
# Domain Configuration
# -----------------------------------------------------------------------------

variable "domain_internal" {
  description = "Internal domain suffix"
  type        = string
  default     = "homelab.rambtech.dev"

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9.-]+[a-z0-9]$", var.domain_internal))
    error_message = "Internal domain must be a valid domain name (e.g., homelab.example.com)."
  }
}

variable "domain_public" {
  description = "Public domain"
  type        = string
  default     = "rambtech.dev"

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9.-]+[a-z0-9]$", var.domain_public))
    error_message = "Public domain must be a valid domain name (e.g., example.com)."
  }
}

# -----------------------------------------------------------------------------
# Cloudflare Configuration (IDs only - tokens from 1Password)
# -----------------------------------------------------------------------------

variable "cloudflare_account_id" {
  description = "Cloudflare account ID"
  type        = string
  default     = ""
}

variable "cloudflare_zone_id" {
  description = "Cloudflare zone ID"
  type        = string
  default     = ""
}

variable "cloudflare_tunnel_id" {
  description = "Cloudflare tunnel ID"
  type        = string
  default     = ""
}

# -----------------------------------------------------------------------------
# Computed Locals
# -----------------------------------------------------------------------------

locals {
  ssh_public_key = file(var.ssh_public_key_path)
}

